// Original exposition: assumptions, derivations, counterexamples and numerical
// checks are kept together so a formula never loses its conditions of use.
const reading = {
  habr: 'https://habr.com/ru/articles/514818/',
  linear: 'https://education.yandex.ru/handbook/ml/article/linear-models',
  probability: 'https://education.yandex.ru/handbook/ml/article/veroyatnostnyj-podhod-v-ml',
  bayes: 'https://education.yandex.ru/handbook/ml/article/bajesovskij-podhod-k-ocenivaniyu',
  statistics: 'https://www.hse.ru/mirror/pubs/share/508524813.pdf'
};

function note(text) { return `<div class="theory-callout">${text}</div>`; }
function cite(key, label) { return `<p class="theory-reading">Продолжить чтение: <a href="${reading[key]}" target="_blank" rel="noreferrer">${label} ↗</a></p>`; }
function table(headers, rows, caption) {
  return `<div class="math-table-scroll" tabindex="0" role="region" aria-label="${caption}"><table class="math-table"><caption>${caption}</caption><thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map((cell, i) => i ? `<td>${cell}</td>` : `<th scope="row">${cell}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function exampleVisual() {
  const sx = x => 65 + x * 115, sy = y => 285 - y * 43;
  const points = [[1, 2], [2, 3], [3, 5], [4, 4]];
  return `<figure class="theory-visual math-figure"><svg viewBox="0 0 680 330" role="img" aria-labelledby="linear-example-caption"><title>МНК на четырёх наблюдениях</title>
    <path class="theory-grid" d="M65 70H610M65 156H610M65 242H610M180 45V285M295 45V285M410 45V285M525 45V285"/>
    <path class="theory-axis" d="M65 38V285H620"/><path class="theory-curve" d="M${sx(0)} ${sy(1.5)}L${sx(4.6)} ${sy(.8 * 4.6 + 1.5)}"/>
    ${points.map(([x,y]) => `<path class="math-residual" d="M${sx(x)} ${sy(y)}V${sy(.8*x+1.5)}"/><circle class="theory-step" cx="${sx(x)}" cy="${sy(y)}" r="6"/><text x="${sx(x)+10}" y="${sy(y)-12}">(${x}, ${y})</text>`).join('')}
    <circle class="math-centroid" cx="${sx(2.5)}" cy="${sy(3.5)}" r="7"/><text x="365" y="160">средние (2.5, 3.5)</text>
    <text x="72" y="30">балл</text><text x="460" y="316">часы подготовки</text><text x="74" y="80">ŷ = 0.8x + 1.5</text>
    </svg><figcaption id="linear-example-caption">Линия проходит через средние. Пунктир — вертикальные ошибки на наблюдениях; МНК минимизирует сумму их квадратов, а не перпендикулярные расстояния до прямой.</figcaption></figure>`;
}

function noiseVisual() {
  const density = [x => Math.exp(-x*x/2)/Math.sqrt(2*Math.PI), x => Math.exp(-Math.SQRT2*Math.abs(x))/Math.SQRT2, x => 1/(Math.PI*(1+x*x))];
  const curves = density.map((f, i) => `<path class="noise-curve noise-${i}" d="${Array.from({length:161}, (_, j) => {const x=-4+j/20;return `${j?'L':'M'}${(60+(x+4)*70).toFixed(2)} ${(265-f(x)*270).toFixed(2)}`;}).join(' ')}"/>`).join('');
  return `<figure class="theory-visual math-figure"><svg viewBox="0 0 680 325" role="img" aria-labelledby="linear-noise-caption"><title>Плотности нормального шума, Лапласа и Коши</title><path class="theory-grid" d="M60 185H620M60 105H620M200 45V265M340 45V265M480 45V265"/><path class="theory-axis" d="M60 35V265H630"/>${curves}<text x="62" y="25">плотность q(ε)</text><text x="335" y="285">0</text><text x="600" y="285">ε</text><text class="noise-label-0" x="75" y="309">Нормальное</text><text class="noise-label-1" x="275" y="309">Лаплас</text><text class="noise-label-2" x="465" y="309">Коши</text></svg><figcaption id="linear-noise-caption">Нормальное N(0,1) и Лаплас с масштабом 1/√2 имеют дисперсию 1. У Коши с масштабом 1 дисперсии и математического ожидания нет; его хвост убывает как 1/ε². Кривые вычислены по плотностям, а не нарисованы произвольно.</figcaption></figure>`;
}

function regularizationVisual() {
  // Isotropic quadratic loss: exact Euclidean projections onto L2/L1 balls.
  const panel = (offset, kind) => {
    const ox=100, oy=245, s=50;
    const center = kind==='l2' ? [2,2] : [2,.3];
    const touch = kind==='l2' ? [Math.SQRT1_2, Math.SQRT1_2] : [1,0];
    const radius = Math.hypot(center[0]-touch[0], center[1]-touch[1])*s;
    const cx=ox+center[0]*s, cy=oy-center[1]*s;
    return `<g transform="translate(${offset} 0)"><text x="30" y="30">${kind==='l2'?'L2: гладкая граница':'L1: касание в углу'}</text><path class="theory-axis" d="M20 ${oy}H340M${ox} 310V45"/>
      <circle class="math-contour" cx="${cx}" cy="${cy}" r="${radius}"/>
      ${kind==='l2'?`<circle class="math-constraint" cx="${ox}" cy="${oy}" r="${s}"/>`:`<path class="math-constraint" d="M${ox+s} ${oy}L${ox} ${oy-s}L${ox-s} ${oy}L${ox} ${oy+s}Z"/>`}
      <circle class="math-centroid" cx="${cx}" cy="${cy}" r="5"/><circle class="theory-step" cx="${ox+touch[0]*s}" cy="${oy-touch[1]*s}" r="6"/>
      <text x="${cx-38}" y="${cy-15}">свободный минимум</text><text x="305" y="250">w₁</text><text x="103" y="60">w₂</text></g>`;
  };
  return `<figure class="theory-visual regularization-geometry math-figure"><svg viewBox="0 0 740 340" role="img" aria-labelledby="linear-penalty-caption"><title>Точные точки касания ограничений L1 и L2 с линией уровня</title>${panel(0,'l2')}${panel(380,'l1')}</svg><figcaption id="linear-penalty-caption">Частный случай квадратичной ошибки с круговыми линиями уровня. Жёлтая граница — допустимые веса; зелёная точка — минимум без ограничения. На L2 оптимум имеет две ненулевые координаты. На L1 в показанном примере w₂=0. Это иллюстрация; общее обоснование разреженности даёт субградиент ниже.</figcaption></figure>`;
}

export function createLinearTheory({ section, notationTable, derivationStack, equationCard }) {
  const blocks = [];
  const add = (id, label, title, body, group) => blocks.push({ id, label, title, body, group });
  const eq = equationCard;
  const proof = (title, steps) => derivationStack(title, steps.map(([formula, explanation]) => ({formula, explanation})));

  add('linear-intro', 'Три взгляда на регрессию', 'Одна прямая, три вопроса и немного паники', `
    <p>Добро пожаловать в главу про <b>ЛИНЕЙНУЮ РЕГРЕССИЮ</b> — первую настоящую модель машинного обучения в этом учебнике. Звучит скромно: «провести прямую через точки». Но за этой прямой прячется добрая половина математики, которая понадобится вам в ML дальше. (Да, я знаю, вы пришли учить нейросети. Нейросети подождут: каждый их слой начинается с той же самой формулы Xw+b.)</p>
    <p>Возьмём простую задачу: по количеству часов подготовки предсказать балл за контрольную. Чтобы честно с ней разобраться, придётся по очереди задать три вопроса:</p>
    <div class="comparison-strip"><article><b>Математический анализ</b><span>«Какая прямая лучшая?» Производные найдут минимум ошибки, а ковариация объяснит наклон.</span></article><article><b>Линейная алгебра</b><span>«Почему именно она и всегда ли она одна?» МНК окажется проекцией, ранг ответит за единственность весов, а спектр — за устойчивость.</span></article><article><b>Теория вероятностей</b><span>«А если бы данные были другими?» Шум делает оценки случайными, а предположения о нём решают, насколько им можно верить.</span></article></div>
    <p>Из багажа понадобятся производная, скалярное произведение, математическое ожидание и дисперсия. Всё остальное введём по ходу, прямо там, где оно впервые понадобится. Первые разделы вообще обходятся без матриц, а к статистике можно вернуться позже, когда наиграетесь с весами в интерактивном модуле.</p>
    ${note('<b>Договоримся о правилах игры.</b> У каждого результата в этой главе есть условия, вычисления и вывод. Формула с обратной матрицей, у которой никто не проверил ранг, или доверительный интервал без модели шума — это не результат, а заклинание. Заклинания мы не учим.')}
  `, 'Начало');

  add('linear-notation', 'Обозначения', 'Кто все эти буквы?', `
    <p>Прежде чем бросаться в формулы, познакомимся с буквами. Их будет много, и, честно, это самая скучная часть главы. Зато потом не придётся гадать, что значит очередная закорючка с шапкой.</p>
    ${notationTable([
      ['n, d, p=d+1', 'число объектов, исходных признаков и параметров с учётом смещения'],
      ['xᵢ, yᵢ', 'признак и ответ i-го объекта в одномерном примере (те самые часы и баллы)'],
      ['a, b', 'наклон и смещение в модели ŷ=ax+b. Осторожно: в некоторых источниках эти буквы переставлены, и это вечный источник путаницы'],
      ['x̄, ȳ', 'средние по выборке: Σxᵢ/n и Σyᵢ/n'],
      ['X₀ ∈ ℝⁿˣᵈ', 'таблица исходных признаков: строка — объект, столбец — признак'],
      ['X=[1 X₀] ∈ ℝⁿˣᵖ', 'матрица дизайна: те же признаки плюс первый столбец из единиц. Он нужен, чтобы спрятать смещение b внутрь β'],
      ['β=(b,w₁,…,w_d)ᵀ', 'все параметры одним столбцом; β̂ («бета с шапкой») — их оценка по данным'],
      ['y, ŷ ∈ ℝⁿ', 'столбец ответов и столбец прогнозов: ŷ=Xβ'],
      ['e=y−ŷ, r=ŷ−y=−e', 'остатки. В литературе встречаются оба знака: в квадрате разницы нет, а вот в градиентах есть'],
      ['ε', 'шум — ненаблюдаемая случайная добавка в истинном механизме. Не путать с остатком e: остаток мы видим, шум — никогда'],
      ['E, Var, Cov', 'математическое ожидание, дисперсия и ковариация'],
      ['U, Y', 'случайные признак и ответ. Букву X оставляем матрице, чтобы не сойти с ума'],
      ['‖v‖²₂=Σvⱼ²', 'квадрат евклидовой нормы, то есть квадрат длины вектора'],
      ['Aᵀ, I, tr(A)', 'транспонирование, единичная матрица и след — сумма диагональных элементов']
    ])}
    <p>Не пугайтесь записи E[ε|X]=0. Она означает всего лишь вот что: если зафиксировать <em>всю</em> матрицу признаков, шум в среднем равен нулю, то есть не тянет ответы систематически вверх или вниз. В чисто алгебраических разделах X и y — просто заданные числа, никакой случайности. Статистические предпосылки появятся позже, и я каждый раз буду говорить, какие именно.</p>
  `, 'Начало');

  add('linear-model', 'Модель и задача', 'Что именно в ней линейного?', `
    <p>Помните прямую y=kx+b из седьмого класса? Когда признаков несколько, каждому достаётся свой коэффициент, а всё вместе удобно записать через матрицу:</p>
    ${eq('ŷᵢ = b + Σ<sub>j=1</sub><sup>d</sup>wⱼxᵢⱼ, &nbsp; ŷ = Xβ', 'Одна строка X, умноженная на β, — это один прогноз. Все строки сразу — весь столбец прогнозов за одну операцию.')}
    <p><b>ВЕС</b> wⱼ показывает, насколько изменится прогноз, если j-й признак вырастет на единицу, а все остальные останутся на месте. Единицы веса — единицы ответа, делённые на единицы признака. Поэтому, если измерить площадь квартиры в см² вместо м², вес уменьшится в 10 000 раз, а прогноз не изменится ни на копейку. Отсюда мораль: большой вес сам по себе ещё не означает «важный признак».</p>
    <p>А теперь вопрос с подвохом: модель b+w₁x+w₂x² линейная? Внезапно, да! По исходному x это парабола, но по весам — обычная линейная комбинация. Именно это и важно: линейная регрессия линейна по <b>ПАРАМЕТРАМ</b>, а не по признакам. А вот exp(wx) уже нелинейна по w, и с ней этот фокус не пройдёт. Значит, всё, что мы дальше докажем про МНК, работает для любых заранее выбранных столбцов X, включая полиномиальные признаки.</p>
  `, 'Начало');

  add('linear-objective', 'Что минимизируем', 'Как измерить, насколько модель неправа?', `
    <p>Чтобы выбрать «лучшую» прямую, сначала нужно договориться, что значит «лучшая». Возьмём ошибку на каждом объекте, возведём в квадрат и усредним:</p>
    ${eq('J(β) = (1/n)‖Xβ−y‖²₂ = (1/n)Σᵢ(ŷᵢ−yᵢ)²', '<b>МНК</b> (OLS) — метод наименьших квадратов. SSE=nJ — сумма квадратов ошибок, то же самое без деления на n.')}
    <p>Зачем квадрат? Он не даёт плюсам и минусам сократиться, сильнее наказывает за большие промахи и, что немаловажно, гладко дифференцируется. Есть и более глубокая причина, связанная с шумом, но до неё дойдём в разделах про вероятность.</p>
    <p>Важная бухгалтерия: все градиенты дальше посчитаны именно для MSE с множителем 1/n. Если взять SSE или J/2, точка минимума останется на месте, а вот градиент и допустимый learning rate изменятся. Масштаб регуляризации тоже придётся пересчитать. (Половина «у меня не сходится, как в статье» растёт именно отсюда.)</p>
    <p>И ещё тонкость. МНК меряет ошибки <b>по вертикали</b>, в единицах ответа. Признаки и таргет в нём не равноправны: если обучить x по y и перевернуть полученную прямую, получится, как правило, другая прямая. А если ошибки измерения сидят в самих признаках, нужна уже отдельная модель.</p>
  `, 'Начало');

  add('linear-scalar-proof', 'Вывод a и b', 'Ищем лучшую прямую через производные', `
    <p><b><em>ВНИМАНИЕ, МАТЕМАТИКА!</em></b> Начинается первый настоящий вывод. Пусть n≥2 и не все xᵢ равны (зачем это нужно, увидим в конце). Будем минимизировать J(a,b)=Σ(axᵢ+b−yᵢ)²/n сразу по двум параметрам.</p>
    <p>Идея простая: в точке минимума гладкой функции все частные производные равны нулю. Найдём их и приравняем к нулю.</p>
    ${proof('От производных до формул', [
      ['∂J/∂b = (2/n)Σᵢ(axᵢ+b−yᵢ) = 0', 'Производная внутреннего выражения по b равна 1, а двойка вылезает из квадрата.'],
      ['aΣᵢxᵢ + nb − Σᵢyᵢ = 0 ⇒ b̂ = ȳ−âx̄', 'Делим на 2/n и раскрываем сумму. Бонус: прямая МНК со свободным членом всегда проходит через точку средних (x̄,ȳ).'],
      ['∂J/∂a = (2/n)Σᵢxᵢ(axᵢ+b−yᵢ) = 0', 'Теперь по a. Цепное правило добавляет множитель xᵢ.'],
      ['âΣᵢxᵢ(xᵢ−x̄) = Σᵢxᵢ(yᵢ−ȳ)', 'Подставляем найденное b̂=ȳ−âx̄ в уравнение по a.'],
      ['Σᵢxᵢ(xᵢ−x̄)=Σᵢ(xᵢ−x̄)², &nbsp; Σᵢxᵢ(yᵢ−ȳ)=Σᵢ(xᵢ−x̄)(yᵢ−ȳ)', 'Фокус с центрированием: добавленные средние ничего не меняют, потому что сумма отклонений от среднего всегда равна нулю.'],
      ['Sₓₓ=Σᵢ(xᵢ−x̄)², &nbsp; Sₓᵧ=Σᵢ(xᵢ−x̄)(yᵢ−ȳ)', 'Дадим этим двум числам имена: они ещё не раз нам встретятся.'],
      ['â = Sₓᵧ/Sₓₓ, &nbsp; b̂ = ȳ−âx̄', 'Sₓₓ>0 по условию, так что делить можно. Вот она, наша прямая!']
    ])}
    ${proof('А это точно минимум, а не максимум?', [
      ['∇²J = (2/n) [[Σxᵢ², Σxᵢ], [Σxᵢ, n]]', 'Гессиан — матрица вторых производных по (a,b). Именно она говорит, куда «загибается» функция.'],
      ['(u,v)∇²J(u,v)ᵀ = (2/n)Σᵢ(uxᵢ+v)²', 'Эта квадратичная форма — сумма квадратов, значит, неотрицательна. А при разных xᵢ она обнуляется только при u=v=0.'],
      ['det(∇²J) = (4/n²)(nΣxᵢ²−(Σxᵢ)²) = 4Sₓₓ/n > 0', 'Гессиан положительно определён, функция строго выпуклая — это «чаша» с единственным дном. Найденная точка — глобальный и единственный минимум.']
    ])}
    ${note('<b>А что, если все x одинаковые?</b> Тогда Sₓₓ=0, и данные просто не умеют различать a и b: любая пара с ac+b=ȳ даёт одну и ту же минимальную ошибку. Представьте, что вы пытаетесь определить наклон прямой по точкам, выстроенным в один вертикальный столбик. Удачи. И отдельно: если заранее запретить смещение, получится â=Σxᵢyᵢ/Σxᵢ², а не формула через центрированную ковариацию.')}
  `, 'Матан');

  add('linear-covariance', 'Ковариация и корреляция', 'Откуда наклон знает про ковариацию?', `
    <p>Формула â=Sₓᵧ/Sₓₓ выглядит как набор закорючек. Но если поделить числитель и знаменатель на n, проступают знакомые лица:</p>
    ${eq('Covₙ(x,y)=Sₓᵧ/n, &nbsp; Varₙ(x)=Sₓₓ/n<br>â = Covₙ(x,y)/Varₙ(x) = ρₙ · sᵧ/sₓ', 'sₓ²=Sₓₓ/n, sᵧ²=Σ(yᵢ−ȳ)²/n; корреляция ρₙ определена при sₓ,sᵧ>0. Если в ковариации и дисперсии одновременно взять n−1, отношение не изменится, так что спор «n или n−1» здесь можно не начинать.')}
    <p><b>КОВАРИАЦИЯ</b> положительна, когда x и y чаще отклоняются от своих средних в одну сторону: больше готовился — выше балл. Деление на дисперсию x переводит это «совместное шевеление» в понятные единицы: на сколько в среднем меняется y, когда x растёт на единицу. А если оба столбца стандартизовать, наклон и вовсе превратится в корреляцию.</p>
    <p>Та же формула живёт не только на конкретной выборке, но и на уровне случайных величин. Вместо среднего по строкам там будет математическое ожидание по распределению:</p>
    ${proof('Та же связь для случайных величин', [
      ['R(a,b)=E[(Y−aU−b)²], &nbsp; E[U²],E[Y²]&lt;∞, &nbsp; Var(U)&gt;0', 'Это риск по распределению, а не среднее по конкретным строкам. Раскрыв квадрат, получаем обычный многочлен от a и b.'],
      ['∂R/∂b=2(aE[U]+b−E[Y])=0 ⇒ b*=E[Y]−a*E[U]', 'Оптимальное смещение снова центрирует модель, как и на выборке.'],
      ['R(a,b*(a))=Var(Y)−2aCov(U,Y)+a²Var(U)', 'Подставляем смещение и раскрываем квадрат центрированных величин.'],
      ['∂R/∂a=−2Cov(U,Y)+2aVar(U)=0 ⇒ a*=Cov(U,Y)/Var(U)', 'Вторая производная 2Var(U)>0, значит, минимум единственный.'],
      ['Y=a₀U+b₀+ε ⇒ a*=a₀+Cov(U,ε)/Var(U)', 'А вот и главное: коэффициент восстанавливает «истинный» a₀, только если признак линейно не связан с шумом. Условия E[ε|U]=0 для этого достаточно. Запомните эту формулу: она вернётся в разделе про пропущенные факторы.']
    ])}
    <p>И сразу предупреждение: нулевая ковариация <b>НЕ</b> означает независимость. Пусть U равномерно распределена на [−1,1], а Y=U². Тогда Cov(U,Y)=E[U³]=0, и лучшая прямая — горизонтальная константа E[Y]=1/3. Хотя Y полностью определяется U! Линейная модель смотрит на параболу и честно говорит: «Никакой связи не вижу». Так прямая может проморгать сильную нелинейную зависимость.</p>
    ${cite('habr', 'Андрей Хлевнюк — «Основы линейной регрессии»')}
  `, 'Матан');

  add('linear-worked-example', 'Пример на четырёх точках', 'Посчитаем руками (да, прям руками)', `
    <p>Хватит букв, давайте числа. Возьмём четырёх школьников: часы подготовки x=(1,2,3,4) и условные баллы y=(2,3,5,4). Данные я, разумеется, придумал, так что выводы об успеваемости по ним делать не надо. (Третий школьник просто очень талантливый.)</p>
    ${table(['x','y','x−x̄','y−ȳ','(x−x̄)(y−ȳ)','ŷ','e=y−ŷ'],[
      ['1','2','−1.5','−1.5','2.25','2.3','−0.3'],['2','3','−0.5','−0.5','0.25','3.1','−0.1'],['3','5','0.5','1.5','0.75','3.9','1.1'],['4','4','1.5','0.5','0.75','4.7','−0.7']
    ],'Полный расчёт одномерного МНК')}
    ${eq('x̄=2.5, &nbsp; ȳ=3.5, &nbsp; Sₓₓ=5, &nbsp; Sₓᵧ=4<br>â=0.8, &nbsp; b̂=1.5, &nbsp; SSE=1.8, &nbsp; MSE=0.45')}
    ${exampleVisual()}
    <p>Проверим, что это действительно оптимум: Σeᵢ=0 и Σxᵢeᵢ=−0.3−0.2+3.3−2.8=0. Это ровно две частные производные из прошлого вывода, и обе равны нулю. Сходится!</p>
    <p>Но не обольщайтесь: эти равенства выполнены, <em>потому что</em> мы так обучили модель. После МНК остатки всегда ортогональны признакам, даже если мир устроен совсем не линейно. Поэтому они ничего не доказывают про независимость ненаблюдаемого шума от признаков.</p>
  `, 'Матан');

  add('linear-analytic', 'Матричный дифференциал', 'Normal equations, или МНК для любого числа признаков', `
    <p>Две производные по a и b — это мило. Но в задаче про квартиры было пять признаков, а в реальной жизни бывают тысячи. Расписывать каждую производную вручную? Нет, спасибо. Вспоминаем линейную алгебру.</p>
    <p>Теперь у нас p параметров, X∈ℝⁿˣᵖ и β∈ℝᵖ. X и y при дифференцировании фиксированы. Малое приращение dβ — столбец той же размерности, что β, а для скалярной функции dJ=(∇J)ᵀdβ. То есть градиент — это то, что стоит перед dβ. Его и будем вылавливать.</p>
    ${proof('Дифференцируем матричную запись', [
      ['r=Xβ−y, &nbsp; J=rᵀr/n, &nbsp; dr=X dβ', 'Умножение на матрицу линейно, поэтому дифференциал остатка получается сразу, без поэлементного разворачивания.'],
      ['dJ = ((dr)ᵀr+rᵀdr)/n = 2rᵀdr/n', 'Оба слагаемых — одно и то же число: скаляр равен своему транспонированию.'],
      ['dJ = (2/n)rᵀX dβ = [(2/n)Xᵀr]ᵀdβ', 'Переставляем множители только через транспонирование. Менять порядок матриц как попало нельзя, это вам не числа.'],
      ['∇J(β)=(2/n)Xᵀ(Xβ−y), &nbsp; ∇²J=(2/n)XᵀX', 'Считываем коэффициент перед dβ — вот и градиент. Дифференцируем ещё раз — получаем гессиан.'],
      ['∇J=0 ⇔ XᵀXβ̂=Xᵀy', 'Это и есть <b>НОРМАЛЬНЫЕ УРАВНЕНИЯ</b>. «Нормальные» тут означает «перпендикулярные», а не «гауссовские» и не «обычные».'],
      ['rank(X)=p ⇒ β̂=(XᵀX)⁻¹Xᵀy', 'Обратная матрица существует, когда столбцы X линейно независимы. В частности, нужно n≥p: объектов не меньше, чем параметров.'],
      ['hᵀ∇²Jh=(2/n)‖Xh‖²&gt;0 для h≠0', 'При полном столбцовом ранге функция строго выпуклая, а минимум единственный и глобальный.']
    ])}
    <p>Тот же градиент можно получить и в лоб, раскрыв J=(βᵀXᵀXβ−2yᵀXβ+yᵀy)/n и вспомнив, что производная βᵀAβ равна (A+Aᵀ)β. Здесь A=XᵀX симметрична, поэтому выходит 2Aβ. Но без симметрии формула «2Aβ» неверна, и на этом регулярно сыпятся на экзаменах.</p>
    ${eq('Размерности: XᵀX — p×p; Xᵀy — p×1; β̂ — p×1', 'Свободный член уже сидит первым элементом β (помните столбец единиц?). Прибавлять после этой формулы ещё один отдельно обученный b не нужно.')}
    ${cite('linear', 'Яндекс Учебник — линейные модели')}
  `, 'Линейная алгебра');

  add('linear-rank', 'Ранг, QR и SVD', 'Что, если веса не единственны?', `
    <p>Представьте, что в таблице квартир кто-то дважды записал площадь: в одном столбце и в другом. Модели всё равно, какой из двух весов увеличить: прибавьте t к одному и вычтите t из другого — прогнозы не изменятся ни на рубль. Значит, «лучших» весов бесконечно много.</p>
    <p>В общем случае такая невидимая добавка — это направление h из <b>ЯДРА</b> матрицы: Xh=0. Данные его просто не видят. Чтобы аккуратно описать все решения, понадобится SVD — сингулярное разложение.</p>
    ${proof('Все решения через компактное SVD', [
      ['X=UᵣΣᵣVᵣᵀ, &nbsp; rank(X)=r, &nbsp; Σᵣ=diag(s₁,…,sᵣ), sⱼ&gt;0', 'Столбцы Uᵣ и Vᵣ ортонормированы. Компактное разложение оставляет только ненулевые сингулярные значения.'],
      ['‖y−Xβ‖²=‖Uᵣᵀy−ΣᵣVᵣᵀβ‖²+‖(I−UᵣUᵣᵀ)y‖²', 'Раскладываем y на часть внутри пространства столбцов X и часть, перпендикулярную ему. По теореме Пифагора квадраты норм складываются, а второе слагаемое от β вообще не зависит: его не победить никакими весами.'],
      ['ΣᵣVᵣᵀβ=Uᵣᵀy ⇒ Vᵣᵀβ=Σᵣ⁻¹Uᵣᵀy', 'Первое слагаемое можно обнулить. Все диагональные значения Σᵣ положительны, так что обращать можно.'],
      ['X⁺=VᵣΣᵣ⁻¹Uᵣᵀ, &nbsp; β̂₀=X⁺y', 'Псевдообратная матрица определена даже при r&lt;p, когда обычной обратной не существует.'],
      ['β̂=X⁺y+h, &nbsp; h∈ker(X)', 'Все МНК-решения отличаются только той самой невидимой для данных компонентой.'],
      ['ŷ=XX⁺y=UᵣUᵣᵀy', 'А вот прогнозы на train единственны, даже когда коэффициенты — нет.'],
      ['‖β̂₀+h‖²=‖β̂₀‖²+‖h‖²', 'β̂₀ лежит в пространстве строк X, перпендикулярном ядру. Поэтому это решение с наименьшей нормой — самое «скромное» из всех.']
    ])}
    <p>Если признаков больше, чем объектов (n&lt;p), полного столбцового ранга не бывает в принципе. А при полном строковом ранге r=n модель может провести поверхность ровно через все точки и получить нулевую ошибку на train. Звучит как победа, но нет: на новом объекте x₀ᵀh может оказаться каким угодно. Классическая дорогая зубрёжка.</p>
    <p>И практический момент: в реальном коде (XᵀX)⁻¹ явно обычно не строят. При полном ранге тонкое QR-разложение X=QR превращает задачу в треугольную систему Rβ̂=Qᵀy, а SVD умеет находить почти зависимые направления. Причина простая: для спектрального числа обусловленности κ₂(XᵀX)=κ₂(X)², то есть нормальные уравнения возводят численную неустойчивость в квадрат.</p>
  `, 'Линейная алгебра');

  add('linear-projection', 'Проекция и R²', 'МНК как тень: почему остаток перпендикулярен признакам', `
    <p>Помните, в уроке про линейную алгебру я обещал, что скалярное произведение и перпендикулярность нам ещё пригодятся? Время пришло. Оказывается, МНК можно доказать вообще без производных — одной теоремой Пифагора.</p>
    <p>Идея такая: все возможные прогнозы Xβ образуют подпространство, натянутое на столбцы X. Настоящий y в него обычно не попадает. Ближайшая к нему точка подпространства — его <b>ПРОЕКЦИЯ</b>, «тень», которую y отбрасывает, если светить строго перпендикулярно.</p>
    ${proof('Геометрическое доказательство МНК', [
      ['P=XX⁺=UᵣUᵣᵀ, &nbsp; Pᵀ=P, &nbsp; P²=P', 'P — ортогональный проектор на пространство столбцов X. Применить его дважды — то же, что один раз: тень от тени — та же тень.'],
      ['ŷ=Py, &nbsp; e=(I−P)y, &nbsp; Xᵀe=0', 'Остаток перпендикулярен всему пространству допустимых прогнозов.'],
      ['y−Xβ=e+(ŷ−Xβ)', 'Разбиваем расстояние до любого кандидата на два перпендикулярных куска.'],
      ['‖y−Xβ‖²=‖e‖²+‖ŷ−Xβ‖² ≥ ‖e‖²', 'Теорема Пифагора: квадрат гипотенузы не меньше квадрата катета. Глобальный минимум доказан, и ни одной производной.']
    ])}
    <p>Если в X есть столбец единиц, то 1ᵀe=0: средний остаток равен нулю, среднее прогнозов равно ȳ, а e перпендикулярен ŷ−ȳ1. При Sᵧᵧ=Σ(yᵢ−ȳ)²&gt;0 отсюда получается знаменитое разложение:</p>
    ${eq('Sᵧᵧ = ‖y−ȳ1‖² = ‖ŷ−ȳ1‖² + SSE<br>R² = 1−SSE/Sᵧᵧ ∈ [0,1]')}
    <p><b>R²</b> — доля разброса y, которую объяснила модель. Для одного признака â=Sₓᵧ/Sₓₓ, поэтому ‖ŷ−ȳ1‖²=â²Sₓₓ=Sₓᵧ²/Sₓₓ и R²=Sₓᵧ²/(SₓₓSᵧᵧ)=ρₙ². В примере с четырьмя школьниками R²=16/25=0.64. Для нескольких признаков это уже не квадрат корреляции с каким-то одним из них.</p>
    ${note('<b>Мелкий шрифт.</b> Разложение и границы [0,1] верны для МНК <b>на train и со смещением</b>. На validation или test R² спокойно бывает отрицательным: модель оказалась хуже, чем константа-среднее. Без смещения или со штрафом ортогональное разложение не гарантировано. А при постоянном y знаменатель равен нулю, и R² не определён вовсе.')}
  `, 'Линейная алгебра');

  add('linear-gradient-derivation', 'Покоординатный градиент', 'Что на самом деле делает кнопка «Один шаг»', `
    <p>Нормальные уравнения — это красиво, но когда признаков сотни тысяч, обращать матрицу p×p — удовольствие сомнительное. (Excel уже не просто подозревает неладное, он ушёл в отпуск.) Поэтому на практике веса часто ищут итеративно, <b>ГРАДИЕНТНЫМ СПУСКОМ</b>: начинаем с каких-нибудь весов и много раз чуть-чуть сдвигаем их туда, где ошибка меньше.</p>
    <p>Для этого нужна производная ошибки по каждому весу. Посчитаем её честно, по одному параметру за раз:</p>
    ${proof('Цепное правило по каждому весу', [
      ['rᵢ=b+Σⱼwⱼxᵢⱼ−yᵢ, &nbsp; J=Σᵢrᵢ²/n', 'Фиксируем знак ошибки: прогноз минус ответ. С другим знаком всё тоже работает, но минусы поедут.'],
      ['∂rᵢ/∂wⱼ=xᵢⱼ, &nbsp; ∂rᵢ/∂b=1', 'Меняем только один параметр, всё остальное считаем константами.'],
      ['∂(rᵢ²)/∂wⱼ=2rᵢxᵢⱼ', 'Производная внешнего квадрата умножается на производную того, что внутри.'],
      ['∂J/∂wⱼ=(2/n)Σᵢrᵢxᵢⱼ', 'Усредняем вклад всех объектов.'],
      ['∂J/∂b=(2/n)Σᵢrᵢ', 'У смещения вместо признака стоит столбец единиц, поэтому остаётся просто сумма остатков.'],
      ['wⱼ ← wⱼ−η∂J/∂wⱼ, &nbsp; b ← b−η∂J/∂b', 'Важно: все производные одного шага считаются по <em>старым</em> параметрам и только потом применяются разом. Обновлять веса по одному и тут же использовать новые — это уже другой алгоритм.']
    ])}
    <p>Проверим на наших четырёх точках. При a=b=0 получаем ∂J/∂a=−19.5 и ∂J/∂b=−7. С η=0.05 первый шаг даст a=0.975, b=0.35. До оптимума (0.8,1.5) ещё далеко, а a даже проскочил мимо, но MSE уже упала с 13.5 примерно до 1.0.</p>
  `, 'Оптимизация');

  add('gradient-direction-proof', 'Почему против градиента', 'Почему шагаем именно против градиента?', `
    <p>Почему минус градиент, а не просто «куда-нибудь вниз»? Представьте, что вы стоите на склоне в густом тумане и видите только землю под ногами. Быстрее всего спуститься, если шагнуть туда, где склон круче всего уходит вниз. Градиент указывает направление самого крутого подъёма, значит, нам в противоположную сторону. Докажем это аккуратно:</p>
    ${proof('Тейлор и Коши–Буняковский', [
      ['J(β+hv)=J(β)+h⟨∇J(β),v⟩+o(h), &nbsp; ‖v‖₂=1', 'Первое приближение Тейлора: при маленьком шаге h изменение функции почти целиком определяется производной по направлению v.'],
      ['⟨∇J,v⟩ ≥ −‖∇J‖₂‖v‖₂ = −‖∇J‖₂', 'Неравенство Коши–Буняковского ограничивает, насколько быстро вообще можно убывать.'],
      ['v*=−∇J/‖∇J‖₂ при ∇J≠0', 'Ровно в направлении антиградиента эта нижняя граница достигается. А если градиент нулевой, все производные первого порядка равны нулю: мы в стационарной точке.']
    ])}
    <p>Но обратите внимание: это утверждение про <em>бесконечно малый</em> шаг. С конечным η нужно ещё учитывать кривизну: даже в правильном направлении слишком длинный шаг перепрыгнет через яму и окажется выше, чем был. Сколько именно «слишком» — в следующем разделе.</p>
  `, 'Оптимизация');

  add('linear-gradient', 'Доказательство сходимости', 'Какой learning rate не взорвёт обучение', `
    <p>Все, кто хоть раз обучал модель, видели, как loss улетает в бесконечность после слишком смелого learning rate. Давайте выясним, где проходит граница. Обозначим H=2XᵀX/n. При полном столбцовом ранге его собственные значения 0&lt;μ₁≤…≤μₚ. Пусть qₜ=βₜ−β̂ — насколько текущие веса отстоят от оптимальных.</p>
    ${proof('Что происходит с ошибкой на каждом шаге', [
      ['∇J(βₜ)=H(βₜ−β̂), &nbsp; qₜ₊₁=(I−ηH)qₜ', 'Вычитаем нормальные уравнения из текущего градиента, и ошибка весов просто умножается на матрицу.'],
      ['H=V diag(μⱼ)Vᵀ, &nbsp; cₜ=Vᵀqₜ', 'Переходим в базис собственных векторов H, где матрица становится диагональной.'],
      ['cₜ₊₁,ⱼ=(1−ημⱼ)cₜ,ⱼ', 'Каждое направление теперь живёт своей жизнью и не мешает остальным.'],
      ['|1−ημⱼ|&lt;1 для всех j ⇔ 0&lt;η&lt;2/μₚ', 'Все компоненты затухают тогда и только тогда, когда шаг меньше 2/μₚ. Отсюда βₜ→β̂.'],
      ['‖qₜ‖₂ ≤ ρᵗ‖q₀‖₂, &nbsp; ρ=maxⱼ|1−ημⱼ|&lt;1', 'Получаем даже скорость: ошибка убывает как геометрическая прогрессия.']
    ])}
    <p>Ровно на границе η=2/μₚ старшая компонента просто меняет знак и не уменьшается: веса качаются туда-сюда. Выше границы она растёт (если присутствовала в начальной ошибке) — привет, NaN в логах. А при неполном ранге нулевые направления не меняются вовсе: прогнозы сходятся, но компонента весов в ядре навсегда остаётся такой, какой была при инициализации.</p>
    ${eq('J(β−ηg)=J(β)−η‖g‖²+(η²/2)gᵀHg, &nbsp; g=∇J(β)', 'Для квадратичной функции формула Тейлора точна, без всяких «приблизительно». При 0&lt;η&lt;2/μₚ и g≠0 из gᵀHg≤μₚ‖g‖² следует, что loss строго убывает на каждом шаге.')}
    ${note('<b>Когда остановиться?</b> На практике — по заданной точности, а не по точному равенству весов. Маленький шаг может означать просто маленький η. Градиент, округлённый до 0.000, может быть ненулевым. А при полном ранге J(β)−J(β̂)≤‖∇J(β)‖²/(2μ₁), поэтому один и тот же «маленький» градиент даёт совсем разные гарантии при разной обусловленности.')}
  `, 'Оптимизация');

  add('linear-conditioning', 'Масштаб и обусловленность', 'Почему похожие признаки тормозят обучение', `
    <p>Представьте чашу ошибки. Если она круглая, антиградиент смотрит прямо в дно, и спуск идёт бодро. А если она вытянута в длинный узкий овраг, антиградиент смотрит в основном поперёк оврага: веса скачут от стенки к стенке и очень медленно ползут вдоль дна.</p>
    <p>Насколько чаша вытянута, измеряет <b>ЧИСЛО ОБУСЛОВЛЕННОСТИ</b> κ=μₚ/μ₁. Даже при лучшем постоянном шаге η*=2/(μ₁+μₚ) худший множитель сжатия равен (κ−1)/(κ+1). При огромном κ он почти равен 1: тысячи шагов почти не двигают веса вдоль слабого направления.</p>
    <p>Стандартизация приводит столбцы к сравнимым масштабам, но почти линейную зависимость она не лечит. Если общая и жилая площадь квартиры почти дублируют друг друга, веса могут уползать в противоположные стороны, пока прогноз стоит на месте. Отсюда важная разница между «прогноз уже стабилен» и «коэффициенты точно определены».</p>
    <p>И правило гигиены: средние и масштабы считаем <b>только на train</b>. Для zⱼ=(xⱼ−mⱼ)/sⱼ и модели b_z+Σw_z,ⱼzⱼ вернуться к исходным единицам можно так: w_x,ⱼ=w_z,ⱼ/sⱼ и b_x=b_z−Σw_z,ⱼmⱼ/sⱼ. А постоянный признак с sⱼ=0 делить на стандартное отклонение нельзя: при наличии смещения он всё равно ничего не добавляет.</p>
  `, 'Оптимизация');

  add('gradient-variants', 'Batch и SGD', 'Batch, mini-batch и SGD: сколько данных на один шаг?', `
    <p>Считать градиент по всем n объектам на каждом шаге — честно, но дорого. Когда строк миллион, хочется схитрить и оценить градиент по случайной кучке объектов:</p>
    ${eq('gₜ=(1/m)Σ<sub>i∈Bₜ</sub>∇ℓᵢ(βₜ), &nbsp; βₜ₊₁=βₜ−ηₜgₜ')}
    <p><b>FULL BATCH</b> использует все n строк, <b>SGD</b> — одну, <b>MINI-BATCH</b> — m строк. Если индексы выбираются равномерно и независимо от прошлых шагов, условное ожидание gₜ равно полному градиенту: в среднем мы идём куда надо, просто с шумом. Только не путайте единицы: <em>эпоха</em> — это просмотр n объектов, <em>шаг</em> — одно обновление. Поэтому «100 шагов» у разных алгоритмов — совсем разный объём работы.</p>
    <p>С постоянным η шум SGD обычно не даёт весам буквально остановиться: они так и дрожат вокруг минимума. Чтобы сойтись точно, нужны дополнительные условия — типично Σηₜ=∞ и Σηₜ²&lt;∞, плюс контроль дисперсии стохастических градиентов и устойчивость итераций. В интерактивном модуле используется полный градиент, поэтому движение детерминировано: повторите обучение с теми же данными и настройками — получите то же самое.</p>
  `, 'Оптимизация');

  add('linear-probability', 'Условное среднее', 'Что на самом деле предсказывает MSE?', `
    <p>До сих пор мы просто минимизировали ошибку на конкретных числах. Пора задать неудобный вопрос: а что мы вообще пытаемся приблизить? Ответ — <b>УСЛОВНОЕ СРЕДНЕЕ</b>.</p>
    <p>Пусть Y=m(U)+ε, где m(u)=E[Y|U=u] — средний ответ при данном значении признака, а E[Y²]&lt;∞. Тогда E[ε|U]=0 просто по определению. Признаки тоже могут быть случайными; при обучении мы видим одну их реализацию.</p>
    ${proof('Почему MSE ищет именно условное среднее', [
      ['Y−g(U) = ε + m(U)−g(U)', 'Добавляем и вычитаем условное среднее — старый добрый трюк. Здесь g — любая функция прогноза с конечным риском.'],
      ['E[(Y−g(U))²|U] = E[ε²|U]+(m(U)−g(U))²+2(m(U)−g(U))E[ε|U]', 'При фиксированном U разность m(U)−g(U) — просто константа.'],
      ['E[(Y−g(U))²|U] = Var(Y|U)+(m(U)−g(U))²', 'Перекрёстное слагаемое обнуляется, потому что шум в среднем равен нулю.'],
      ['argmin<sub>g</sub>E[(Y−g(U))²] = m(U) почти наверное', 'Осталось минимизировать неотрицательный квадрат, и ноль достигается при g=m. Заметьте: нормальность шума нигде не понадобилась!']
    ])}
    <p>Если ограничиться прямыми, мы найдём лучшую <em>линейную</em> аппроксимацию m(U). С самим m(U) она совпадёт, только если условное среднее действительно линейно. Идеально сошедшийся градиентный спуск не исправит неправильно выбранный класс функций: он найдёт лучшую прямую, а не лучшую кривую.</p>
    ${note('<b>Три предположения, которые часто сваливают в одну кучу.</b> E[ε|X]=0 достаточно, чтобы МНК был несмещённым при полном ранге. Постоянная дисперсия и некоррелированность нужны для классической формулы дисперсии. Нормальность добавляет точные распределения оценок и статистик на конечной выборке. Это три разные ступеньки, и каждая — отдельная гипотеза о мире.')}
  `, 'Вероятность и статистика');

  add('linear-loss-derivation', 'Нормальный шум → MSE', 'Откуда берётся квадрат: нормальный шум и правдоподобие', `
    <p>Помните, я обещал объяснить, почему в MSE именно квадрат? Вот объяснение. Предположим, что условно на X шум ε∼N(0,σ²I), σ²&gt;0: ошибки независимы, нормальны и имеют одну и ту же дисперсию. Обратите внимание: нормальными должны быть именно ошибки, а сами признаки и ответы — не обязаны.</p>
    <p>Метод <b>МАКСИМАЛЬНОГО ПРАВДОПОДОБИЯ</b> предлагает выбрать такие параметры, при которых наблюдаемые данные выглядят наиболее «ожидаемыми».</p>
    ${proof('От плотности к оптимизации', [
      ['p(y|X,β,σ²)=(2πσ²)<sup>−n/2</sup> exp(−‖y−Xβ‖²/(2σ²))', 'Совместная плотность — произведение n нормальных плотностей. Это именно плотность: вероятность получить ровно такие y для непрерывных величин равна нулю.'],
      ['−log p = (n/2)log(2πσ²)+SSE(β)/(2σ²)', 'Логарифм превращает произведение в сумму — и внезапно появляется SSE.'],
      ['argmin<sub>β</sub>(−log p)=argmin<sub>β</sub>SSE(β)=β̂<sub>OLS</sub>', 'При фиксированной дисперсии константа и положительный множитель не влияют на то, где минимум. Максимум правдоподобия — это минимум суммы квадратов. Бинго!'],
      ['∂(−log p)/∂v=n/(2v)−SSE/(2v²)=0, &nbsp; v=σ²', 'Если дисперсия неизвестна, её тоже можно оценить: дифференцируем по v=σ².'],
      ['σ̂²<sub>MLE</sub>=SSE(β̂)/n', 'При SSE>0 это оптимум по v>0. Но несмещённая оценка другая, SSE/(n−p); почему — разберём через пару разделов.']
    ])}
    <p>Есть и вырожденный случай: если SSE=0 (например, при интерполяции), правдоподобие неограниченно растёт при σ²→0, и конечной MLE с положительной дисперсией нет. А ЦПТ иногда оправдывает приближённую нормальность, когда шум складывается из множества мелких влияний, но не доказывает её для любого шума. (Источник фразы «шум всегда нормальный» — поверь мне, брат. Не верьте.)</p>
    ${cite('probability', 'Яндекс Учебник — вероятностный подход в ML')}
  `, 'Вероятность и статистика');

  add('linear-noise-laws', 'Другие распределения шума', 'А если шум не нормальный?', `
    <p>Нормальный шум дал нам MSE. Логичный вопрос: а если шум другой? Для независимых ошибок с известной общей плотностью q и фиксированными параметрами масштаба отрицательное лог-правдоподобие равно Σᵢ−log q(eᵢ), где eᵢ=yᵢ−xᵢᵀβ. Получается, каждая гипотеза о шуме автоматически рождает свою функцию потерь:</p>
    ${table(['Шум','Плотность / поддержка','−log q(e) с точностью до константы','Следствие'],[
      ['Нормальный','q(e)∝exp(−e²/(2σ²))','e²/(2σ²)','МНК; штраф растёт квадратично, большие промахи наказываются очень больно.'],
      ['Лаплас, масштаб c>0','q(e)=exp(−|e|/c)/(2c)','|e|/c','MAE; в точечной задаче оптимальна условная медиана.'],
      ['Стьюдент, ν>0, масштаб s>0','q(e)∝(1+e²/(νs²))<sup>−(ν+1)/2</sup>','((ν+1)/2)log(1+e²/(νs²))','Хвосты штрафуются мягче, но оптимизация в общем случае невыпуклая.'],
      ['Коши, масштаб c>0','q(e)=1/[πc(1+(e/c)²)]','log(1+(e/c)²)','Частный случай ν=1; нет ни среднего, ни дисперсии, так что привычные рассуждения про MSE-риск не работают.'],
      ['Равномерный на [−c,c]','q(e)=1/(2c) при |e|≤c, иначе 0','Константа внутри, +∞ снаружи','При известном c все допустимые веса одинаково правдоподобны: правдоподобие ничего не выбирает.']
    ],'Связь распределения шума с обучением')}
    ${noiseVisual()}
    <p>У Лапласа конечная дисперсия 2c². Поэтому при нулевом условном среднем МНК всё ещё несмещён, хотя уже не совпадает с MLE. У Стьюдента среднее существует при ν&gt;1, дисперсия — при ν&gt;2. Симметричная плотность сама по себе ещё не гарантирует, что у неё есть математическое ожидание. (Коши передаёт привет.)</p>
    <p>Если у равномерного шума неизвестен масштаб, его MLE при фиксированных весах равна maxᵢ|eᵢ|. Подставив её, получим задачу минимизации <em>максимального</em> модуля остатка, а не суммы квадратов. И при точной интерполяции масштаб снова вырождается в ноль.</p>
    <p>Асимметричный шум с конечным средним можно центрировать, но у такого шума центр, медиана и среднее — вообще разные числа. Например, ε=Z−1 для Z∼Exp(1) имеет среднее 0, но медиану log 2−1. Тогда MSE и MAE решают разные задачи даже на бесконечных данных.</p>
    ${note('<b>Частая ошибка:</b> посмотреть на гистограмму таргета и сделать вывод о шуме. Распределение шума — это отклонения ответов <em>при фиксированных признаках</em>, а не распределение самих ответов. И даже нормальность обученных остатков ещё не означает, что истинные ошибки независимы.')}
  `, 'Вероятность и статистика');

  add('linear-estimator', 'Несмещённость и дисперсия', 'Насколько случайны найденные коэффициенты?', `
    <p>Мысленный эксперимент. Соберите другую группу школьников — получите другие веса. Ещё одну — снова другие. Получается, β̂ — это <b>СЛУЧАЙНАЯ ВЕЛИЧИНА</b>, и у неё можно спросить среднее и разброс.</p>
    <p>Предположим y=Xβ₀+ε, rank(X)=p, E[ε|X]=0 и конечную Ω=Cov(ε|X). Положим A=(XᵀX)⁻¹Xᵀ, тогда AX=I.</p>
    ${proof('Два свойства линейной оценки', [
      ['β̂=Ay=AXβ₀+Aε=β₀+Aε', 'Вся случайность весов — это линейное преобразование шума.'],
      ['E[β̂|X]=β₀+A E[ε|X]=β₀', 'Условная несмещённость: в среднем по повторным выборкам попадаем ровно в β₀. Если безусловное ожидание существует, то и E[β̂]=β₀.'],
      ['Cov(β̂|X)=AΩAᵀ', 'При фиксированном X матрица A постоянна, и ковариация преобразуется слева и справа.'],
      ['Ω=σ²I ⇒ Cov(β̂|X)=σ²(XᵀX)⁻¹', 'Используем AAᵀ=(XᵀX)⁻¹. И снова нормальность не понадобилась.']
    ])}
    ${eq('Var(â|x)=σ²/Sₓₓ<br>Var(b̂|x)=σ²(1/n+x̄²/Sₓₓ)<br>Cov(â,b̂|x)=−σ²x̄/Sₓₓ', 'Одномерный случай: â−a₀=Σ(xᵢ−x̄)εᵢ/Sₓₓ, b̂−b₀=ε̄−x̄(â−a₀). Из Σ(xᵢ−x̄)=0 следует Cov(ε̄,â)=0, а подстановка даёт все три формулы.')}
    <p>Посмотрите на σ²/Sₓₓ: чем шире разброс x, тем точнее оценивается наклон при том же шуме. Интуитивно понятно: по точкам, сбившимся в кучку, наклон определить сложно, а по разбросанным — легко. Отсюда же неустойчивость при маленьком Sₓₓ.</p>
    <p>И про слово «несмещённая»: оно значит «правильная <em>в среднем</em> по повторным выборкам», а не «точная в каждом конкретном наборе». Несмещённый стрелок может каждый раз промахиваться на метр — просто то влево, то вправо.</p>
  `, 'Вероятность и статистика');

  add('linear-gauss-markov', 'Теорема Гаусса–Маркова', 'В каком смысле МНК — лучший?', `
    <p>Красивое утверждение с громким названием. При полном ранге, E[ε|X]=0 и Cov(ε|X)=σ²I МНК имеет наименьшую условную дисперсию среди всех оценок, которые <em>линейны по y</em> и несмещены при любом β₀. Такие оценки называют <b>BLUE</b> — Best Linear Unbiased Estimator. И нет, нормальность снова не нужна.</p>
    ${proof('Доказательство через произвольного конкурента', [
      ['β̃=Cy, &nbsp; E[β̃|X]=CXβ₀', 'Берём произвольного конкурента. C может зависеть от X, но не от ответов y.'],
      ['E[β̃|X]=β₀ для любого β₀ ⇔ CX=I', 'Требование несмещённости при любом β₀ превращается в матричное условие.'],
      ['C=A+D, &nbsp; A=(XᵀX)⁻¹Xᵀ ⇒ DX=0', 'Отделяем МНК-часть от «авторской добавки» конкурента.'],
      ['ADᵀ=(XᵀX)⁻¹XᵀDᵀ=(XᵀX)⁻¹(DX)ᵀ=0', 'Перекрёстные члены в ковариации исчезают.'],
      ['Cov(β̃|X)−Cov(β̂|X)=σ²DDᵀ', 'Раскрываем σ²(A+D)(A+D)ᵀ: от разницы остаётся только σ²DDᵀ.'],
      ['vᵀ[Cov(β̃|X)−Cov(β̂|X)]v=σ²‖Dᵀv‖²≥0', 'Ни одну линейную комбинацию коэффициентов конкурент не оценит с меньшей дисперсией. МНК победил.']
    ])}
    <p>Но читайте условия теоремы, а не только название. Она не утверждает, что МНК лучше всех возможных процедур, и не запрещает ridge иметь меньшую среднеквадратичную ошибку: ridge просто играет не по этим правилам и допускает смещение. А при гетероскедастичности условие σ²I нарушается, и вывод больше не следует.</p>
    ${cite('statistics', 'О. А. Демидова, НИУ ВШЭ — классическая линейная регрессия')}
  `, 'Вероятность и статистика');

  add('linear-inference', 'Дисперсия и интервалы', 'От остатков к доверительным интервалам', `
    <p>Мы знаем, что Cov(β̂|X)=σ²(XᵀX)⁻¹. Одна проблема: σ² нам никто не сообщил. Придётся оценить её по остаткам. Пусть n&gt;p и выполнены условия прошлого раздела. Остаток e=(I−P)ε; матрица M=I−P симметрична, идемпотентна и имеет ранг n−p.</p>
    ${proof('Почему делим на n−p', [
      ['SSE=eᵀe=εᵀMε', 'Пользуемся M²=M и MX=0: истинные веса из остатков исчезают.'],
      ['E[εᵀMε|X]=ΣᵢΣⱼMᵢⱼE[εᵢεⱼ|X]=σ²tr(M)', 'При нулевом среднем и Ω=σ²I выживают только диагональные слагаемые.'],
      ['tr(M)=n−p ⇒ E[SSE|X]=(n−p)σ²', 'У P ровно p собственных значений, равных 1, поэтому у M=I−P единиц n−p, а остальные — нули.'],
      ['s²=SSE/(n−p) ⇒ E[s²|X]=σ²', 'p оценённых параметров «съели» p степеней свободы. Поэтому MSE=SSE/n систематически занижает σ²: модель подогнана под те же точки и выглядит точнее, чем есть.']
    ])}
    <p>Теперь добавим нормальность ε|X∼N(0,σ²I). Тогда β̂|X∼N(β₀,σ²(XᵀX)⁻¹). А SSE/σ² после ортогонального поворота превращается в сумму квадратов n−p независимых стандартных нормальных величин, то есть имеет распределение χ² с n−p степенями свободы.</p>
    ${proof('От нормального числителя к t-статистике', [
      ['Cov(Aε,Mε|X)=σ²AM=0', 'AM=0. Совместно нормальные векторы с нулевой ковариацией независимы, поэтому β̂ не зависит от s².'],
      ['Zⱼ=(β̂ⱼ−β₀,ⱼ)/(σ√{[(XᵀX)⁻¹]ⱼⱼ}) ∼ N(0,1)', 'Стандартизуем одну координату.'],
      ['Tⱼ=Zⱼ/√[(SSE/σ²)/(n−p)] ∼ t<sub>n−p</sub>', 'Отношение нормальной величины к корню из независимой нормированной χ² имеет распределение Стьюдента. (Того самого, который на самом деле Госсет из пивоварни Guinness.)'],
      ['β̂ⱼ ± t<sub>1−α/2,n−p</sub> · s√{[(XᵀX)⁻¹]ⱼⱼ}', 'Переворачиваем неравенство |Tⱼ|≤квантиль и получаем доверительный интервал уровня 1−α.']
    ])}
    <p>Теперь самая частая ошибка в интерпретации. «95%» — это доля интервалов, которые накроют фиксированный истинный параметр, если повторять эксперимент много раз. Это <em>не</em> вероятность того, что параметр лежит в уже посчитанном частотном интервале. Проверка гипотезы H₀:βⱼ=c использует |(β̂ⱼ−c)/SEⱼ| и ту же t-квантиль. И статистическая значимость — это не «большой эффект» и уж точно не причинность.</p>
    <p>Без нормального шума эти t-интервалы на малой выборке в общем случае не точны. Асимптотическим интервалам нужны условия ЦПТ и подходящая оценка ковариации. А при n≤p формула s² с делением на n−p вообще не работает.</p>
  `, 'Вероятность и статистика');

  add('linear-prediction', 'Среднее и новый ответ', 'Почему новый ответ предсказать сложнее, чем среднее', `
    <p>Есть два очень похожих вопроса, которые постоянно путают. «Какой <em>средний</em> балл у всех, кто готовился 2.5 часа?» и «Какой балл получит <em>конкретный</em> Вася, который готовился 2.5 часа?» Во втором случае к неуверенности в весах добавляется ещё и личный шум Васи.</p>
    <p>Формально: пусть x₀ — новый столбец из p признаков, включая единицу, μ₀=x₀ᵀβ₀ и μ̂₀=x₀ᵀβ̂. При той же нормальной модели и независимом новом шуме ε₀ дисперсии равны:</p>
    ${eq('Var(μ̂₀−μ₀|X,x₀)=σ²h₀, &nbsp; h₀=x₀ᵀ(XᵀX)⁻¹x₀<br>Var(Y₀−μ̂₀|X,x₀)=σ²(1+h₀)', 'Y₀=μ₀+ε₀: к неуверенности в среднем добавляется дисперсия нового независимого шума σ².')}
    ${eq('Интервал среднего: μ̂₀ ± t<sub>1−α/2,n−p</sub>s√h₀<br>Предиктивный интервал: μ̂₀ ± t<sub>1−α/2,n−p</sub>s√(1+h₀)')}
    <p>Посчитаем. В одномерном случае h₀=1/n+(x₀−x̄)²/Sₓₓ. В нашем примере s²=1.8/2=0.9. При x₀=2.5 получаем h₀=0.25 и μ̂₀=3.5. С t₀.₉₇₅,₂≈4.303 интервал для среднего — примерно [1.46,5.54], а для нового ответа — [−1.06,8.06]. Отрицательный балл, ага. Четыре точки дают очень мало уверенности.</p>
    <p>Чем дальше x₀ от x̄, тем шире оба интервала. Но помните: они описывают неуверенность <em>внутри принятой модели</em>. Если за пределами train зависимость меняется, даже широкий гауссовский интервал окажется самоуверенным. А отрицательная нижняя граница для заведомо неотрицательного ответа — скорее сигнал, что модель тут неуместна, чем повод молча обрезать интервал по нулю.</p>
  `, 'Вероятность и статистика');

  add('linear-heteroskedasticity', 'Неодинаковый и зависимый шум', 'Что, если шум у всех разный?', `
    <p>Вернёмся к квартирам. Ошибка прогноза цены однушки на окраине — плюс-минус пара сотен тысяч. Для пентхауса в Москва-Сити — плюс-минус пара десятков миллионов. Шум с разной дисперсией называют <b>ГЕТЕРОСКЕДАСТИЧНЫМ</b>. (Да, это слово нужно уметь выговорить на экзамене.)</p>
    <p>При Ω≠σ²I оценка β̂ остаётся несмещённой, если E[ε|X]=0. А вот классическая формула ковариации врёт; правильная — (XᵀX)⁻¹XᵀΩX(XᵀX)⁻¹. В общем случае Ω может иметь разные дисперсии на диагонали и ненулевые ковариации между строками.</p>
    ${proof('Обобщённый МНК при известной Ω≻0', [
      ['Q(β)=(y−Xβ)ᵀΩ⁻¹(y−Xβ)', 'Штрафуем остатки с учётом их масштаба и зависимости: шумным наблюдениям — меньше доверия.'],
      ['dQ=−2(y−Xβ)ᵀΩ⁻¹X dβ', 'Ω⁻¹ симметрична и от β не зависит.'],
      ['β̂<sub>GLS</sub>=(XᵀΩ⁻¹X)⁻¹XᵀΩ⁻¹y', 'При полном столбцовом ранге XᵀΩ⁻¹X положительно определена, так что обращаем смело.'],
      ['X*=Ω⁻¹ᐟ²X, &nbsp; y*=Ω⁻¹ᐟ²y, &nbsp; Cov(ε*|X)=I', 'После «отбеливания» шум становится обычным, и это снова МНК. Значит, работает теорема Гаусса–Маркова.'],
      ['Cov(β̂<sub>GLS</sub>|X)=(XᵀΩ⁻¹X)⁻¹', 'Линейное преобразование шума даёт ковариацию оценки.']
    ])}
    <p>Частный случай Ω=diag(σᵢ²) — <b>ВЗВЕШЕННЫЙ МНК</b>: минимизируем Σeᵢ²/σᵢ². Чем точнее наблюдение, тем больше его вес. Формулы не меняются, если Ω известна с точностью до общего положительного множителя.</p>
    ${eq('V̂<sub>HC0</sub>=(XᵀX)⁻¹Xᵀ diag(eᵢ²) X(XᵀX)⁻¹', 'Оценка ковариации, робастная к гетероскедастичности. Веса МНК она не меняет — только стандартные ошибки.')}
    <p>HC0 — асимптотическая оценка, а не гарантия для любых четырёх строк. Ей нужны независимые наблюдения, подходящие моменты и отсутствие доминирующих точек при росте n. Для временной зависимости используют HAC-оценки, для групповой — кластерные. Просто подставить eᵢ² в HC0 при зависимых строках недостаточно.</p>
  `, 'Вероятность и статистика');

  add('linear-consistency', 'Состоятельность и смещение', 'Чего не исправит даже бесконечная выборка', `
    <p>Популярная надежда: «Соберём побольше данных, и всё само станет правильно». Иногда так и есть. Иногда — нет, и это обиднее всего. Разберёмся, когда.</p>
    ${proof('Когда МНК приближается к истинным весам', [
      ['β̂−β₀=(XᵀX/n)⁻¹(Xᵀε/n)', 'Переписываем ошибку оценки как произведение двух средних по наблюдениям.'],
      ['XᵀX/n → Q≻0, &nbsp; Xᵀε/n → 0 по вероятности', 'Достаточные условия: например, i.i.d. строки, конечные вторые моменты, E[xᵢεᵢ]=0 и невырожденная E[xᵢxᵢᵀ].'],
      ['β̂ → β₀ по вероятности', 'Обращение непрерывно около невырожденной Q, а второй множитель уходит в ноль.']
    ])}
    <p><b>НЕСМЕЩЁННОСТЬ</b> — свойство среднего на конечной выборке, <b>СОСТОЯТЕЛЬНОСТЬ</b> — предел при n→∞. Одно не заменяет другое. А при E[xε]≠0 предел будет β₀+Q⁻¹E[xε]: чем больше данных, тем <em>точнее</em> мы оцениваем <em>неправильный</em> коэффициент. Уверенно и мимо.</p>
    ${eq('Y=a₀U+γZ+b₀+ε, &nbsp; Cov(U,ε)=0<br>Если Z пропустить: a*=a₀+γCov(U,Z)/Var(U)', 'Достаточно одного коррелированного пропущенного фактора, чтобы наклон поехал. Это точный вывод из ковариационной формулы — той самой, что я просил запомнить.')}
    <p>Пример: Z — насколько ученик был подготовлен ещё до курса. Он влияет и на часы подготовки, и на балл. Не включили Z в модель — и коэффициент при часах приписывает себе чужие заслуги.</p>
    <p>Ошибки измерения признака тоже коварны. Если вместо U мы наблюдаем W=U+δ, где δ имеет нулевое среднее и независима от U и ε, то регрессия Y=a₀U+b₀+ε на W имеет наклон a₀Var(U)/(Var(U)+Var(δ)). Он прижат к нулю. Ни регуляризация, ни лишние итерации это смещение не уберут.</p>
  `, 'Вероятность и статистика');

  add('linear-regularization', 'Ridge: точная формула', 'Ridge: штрафуем веса, но не смещение', `
    <p>Помните, как веса уползали в разные стороны при почти одинаковых признаках? Самое простое лекарство — запретить им быть большими. Добавим к ошибке штраф за размер весов, и получится <b>RIDGE-РЕГРЕССИЯ</b> (она же L2-регуляризация, она же регуляризация Тихонова).</p>
    <p>В нашем модуле штрафуются только веса признаков, а смещение b — нет. (Зачем штрафовать модель за то, что средняя цена квартиры в Москве не равна нулю?) Для общей β=(b,wᵀ)ᵀ введём D=diag(0,1,…,1).</p>
    ${proof('Матричный вывод ridge', [
      ['Jλ(β)=‖Xβ−y‖²/n+λβᵀDβ, &nbsp; λ≥0', 'Это обычная MSE плюс λΣwⱼ².'],
      ['∇Jλ=(2/n)Xᵀ(Xβ−y)+2λDβ', 'Штраф добавляет производную только по весам, смещение не трогаем.'],
      ['(XᵀX+nλD)β̂λ=Xᵀy', 'Множитель n возникает из-за того, что мы усредняем MSE. С SSE его бы не было.'],
      ['β̂λ=(XᵀX+nλD)⁻¹Xᵀy при λ>0', 'hᵀ(XᵀX+nλD)h=‖Xh‖²+nλΣhⱼ²: ноль возможен, только если все веса h нулевые, а затем столбец единиц обнуляет и смещение. Для непустой выборки матрица обратима — даже при дублирующихся признаках!']
    ])}
    <p>Можно и по-другому: центрируем X_c=X₀−1x̄ᵀ и y_c=y−ȳ1, решаем ŵλ=(X_cᵀX_c+nλI)⁻¹X_cᵀy_c, а потом находим b̂λ=ȳ−x̄ᵀŵλ. Так сразу видно, почему штраф не тянет средний прогноз к нулю.</p>
  `, 'Регуляризация и практика');

  add('linear-regularization-deep', 'Bias–variance весов', 'Bias и variance весов: бесплатных обедов не бывает', `
    <p>Ridge выглядит как читерство: добавили штраф — и всё стало устойчивым. Но бесплатных обедов не бывает, так что посмотрим, чем именно мы платим. Рассмотрим центрированную задачу для весов, A=X_cᵀX_c, k=nλ&gt;0. Условно на дизайн предполагаем E[ε]=0 и Cov(ε)=σ²I до центрирования; в произведении X_cᵀε центрирование шума ничего не меняет.</p>
    ${eq('E[ŵλ|X]−w₀=−k(A+kI)⁻¹w₀<br>Cov(ŵλ|X)=σ²(A+kI)⁻¹A(A+kI)⁻¹')}
    <p>Первая формула — это bias: ridge в среднем промахивается. Она получается из E[ŵλ]=(A+kI)⁻¹Aw₀ и равенства A=(A+kI)−kI. Вторая — variance, разброс от выборки к выборке; она следует из правила Cov(Bε)=B Cov(ε) Bᵀ.</p>
    ${eq('В направлении с собственным значением dⱼ&gt;0:<br>biasⱼ=−kθⱼ/(dⱼ+k), &nbsp; varianceⱼ=σ²dⱼ/(dⱼ+k)²<br>MSEⱼ=(k²θⱼ²+σ²dⱼ)/(dⱼ+k)²', 'θⱼ — истинный коэффициент в этом собственном направлении. Для сравнения: у МНК varianceⱼ=σ²/dⱼ и biasⱼ=0.')}
    <p>Вот и весь торг. При dⱼ≈0 дисперсия МНК огромна, а ridge её резко уменьшает. Но если истинный θⱼ большой, слишком сильный штраф даст заметный bias. Поэтому универсального λ для всех задач нет, его подбирают на validation. А в сингулярном направлении dⱼ=0 данных про θⱼ нет вообще: ridge просто ставит ноль, а не «восстанавливает истину».</p>
    <p>Через SVD X_c=UΣVᵀ картина ещё нагляднее: множитель в направлении j меняется с 1/sⱼ у МНК на sⱼ/(sⱼ²+nλ) у ridge. Маленькие сингулярные значения больше не взрывают решение — вот и вся магия.</p>
  `, 'Регуляризация и практика');

  add('linear-lasso-geometry', 'L1 и L2', 'L1 против L2: почему Lasso умеет обнулять веса', `
    <p>Если в ridge заменить квадраты весов на модули, получится <b>LASSO</b> (L1-регуляризация). Казалось бы, мелочь. Но у Lasso есть суперспособность: он может сделать вес <em>ровно</em> нулевым, то есть сам выкинуть ненужный признак. Ridge так не умеет: он прижимает веса к нулю, но почти никогда не обнуляет. Почему? Сначала картинка:</p>
    ${regularizationVisual()}
    <p>Теперь строго. У модуля в нуле излом, и обычной производной там нет. Поэтому используем <b>СУБГРАДИЕНТ</b> — множество всех допустимых «наклонов» в точке излома.</p>
    ${proof('Условие оптимума Lasso', [
      ['min<sub>w</sub> J(w)+λΣⱼ|wⱼ|', 'В центрированной задаче свободный член восстанавливается отдельно, его не штрафуем.'],
      ['∂|wⱼ|={sign(wⱼ)} при wⱼ≠0; &nbsp; ∂|0|=[−1,1]', 'Вне нуля всё как обычно, а в нуле у модуля целый отрезок возможных наклонов.'],
      ['0∈∂ⱼJ+λ∂|wⱼ|', 'Для выпуклой функции это необходимое и достаточное условие оптимума по координате при остальных зафиксированных.'],
      ['wⱼ=0 допустим в оптимуме ⇔ |∂ⱼJ|≤λ', 'Вот и секрет: L1 может «погасить» ненулевой градиент ошибки прямо в нуле, если тот не слишком большой. У гладкого L2 производная штрафа в нуле равна нулю, поэтому при любом ненулевом градиенте ошибки вес из нуля уйдёт.']
    ])}
    <p>Особенно красиво всё выглядит, когда признаки ортонормированы: X_cᵀX_c/n=I. Тогда при c=X_cᵀy_c/n получаем J(w)=Σⱼ(wⱼ−cⱼ)²+const, и условие выше даёт ŵⱼ=sign(cⱼ)max(|cⱼ|−λ/2,0). Порог именно λ/2, потому что у нас MSE без множителя 1/2 (снова бухгалтерия). При коррелированных столбцах координаты уже не независимы.</p>
    ${proof('Вывод мягкого порога для одной координаты', [
      ['wⱼ&gt;0: 2(wⱼ−cⱼ)+λ=0 ⇒ wⱼ=cⱼ−λ/2', 'Эта ветка согласована со знаком wⱼ только при cⱼ&gt;λ/2.'],
      ['wⱼ&lt;0: 2(wⱼ−cⱼ)−λ=0 ⇒ wⱼ=cⱼ+λ/2', 'Отрицательная ветка требует cⱼ&lt;−λ/2.'],
      ['wⱼ=0: 0∈−2cⱼ+λ[−1,1] ⇔ |cⱼ|≤λ/2', 'Если ни одна ненулевая ветка не подходит, ноль оказывается внутри отрезка субградиентов. Три случая — одна формула soft-thresholding: маленькие коэффициенты обнуляются, большие сдвигаются к нулю на λ/2.']
    ])}
    <p>Две оговорки. Из нескольких коррелированных признаков L1 часто выбирает один, но это не доказывает, что именно он причинно важен: возможно, ему просто повезло. И штрафы зависят от единиц измерения, так что масштабирование перед ridge и lasso должно быть осмысленным.</p>
  `, 'Регуляризация и практика');

  add('linear-bayes', 'Байесовский взгляд', 'Байесовский взгляд: MAP и веса после данных', `
    <p>До сих пор веса были фиксированными неизвестными числами. Байесовцы смотрят иначе: раз мы не знаем веса, опишем своё незнание распределением. До данных это <b>PRIOR</b> (априорное распределение), после — <b>POSTERIOR</b> (апостериорное). И внезапно окажется, что ridge — это байесовский вывод, просто в другой одежде.</p>
    <p>Рассмотрим модель y|β,X∼N(Xβ,σ²I) с известной σ² и собственным нормальным prior β∼N(m₀,V₀), V₀≻0.</p>
    ${proof('Дополняем квадрат в апостериорной плотности', [
      ['−2log p(β|X,y)=‖y−Xβ‖²/σ²+(β−m₀)ᵀV₀⁻¹(β−m₀)+const', 'Формула Байеса: posterior пропорционален likelihood × prior. Берём −2log, чтобы произведение стало суммой.'],
      ['Vₙ⁻¹=XᵀX/σ²+V₀⁻¹, &nbsp; h=Xᵀy/σ²+V₀⁻¹m₀', 'Раскрываем скобки: квадратичная по β часть равна βᵀVₙ⁻¹β−2βᵀh.'],
      ['mₙ=Vₙh ⇒ βᵀVₙ⁻¹β−2βᵀh=(β−mₙ)ᵀVₙ⁻¹(β−mₙ)+const', 'Дополняем до полного квадрата, как в школе, только с матрицами. Сразу видны и центр, и кривизна.'],
      ['β|X,y∼N(mₙ,Vₙ), &nbsp; β̂<sub>MAP</sub>=E[β|X,y]=mₙ', 'Posterior снова нормальный. Для этой модели мода совпадает со средним; в общем случае это не так.'],
      ['Y₀|x₀,X,y∼N(x₀ᵀmₙ, σ²+x₀ᵀVₙx₀)', 'Интегрируем неопределённость весов и добавляем независимый шум нового ответа.']
    ])}
    ${eq('Prior w∼N(0,τ²I) ⇒ λ<sub>MSE</sub>=σ²/(nτ²)', 'Умножаем отрицательный log-posterior на 2σ²/n. Если бы loss был SSE, а не MSE, коэффициент был бы σ²/τ². Узкий prior (маленькое τ) — сильная регуляризация.')}
    <p>Чтобы получить ровно ridge из модуля, где b не штрафуется, ставим нормальный prior только на w и плоский prior на b. Плоская плотность на всей прямой не нормируется, так что это <em>несобственный</em> prior, а не подстановка в V₀≻0. Для непустой выборки posterior всё равно остаётся собственным благодаря столбцу единиц и штрафу на все веса.</p>
    <p>А лапласовский prior на w даёт L1-штраф, то есть Lasso. Только не путайте его с лапласовским <em>шумом</em>: prior меняет регуляризацию, а шум — loss на данных. И ещё: байесовский интервал имеет вероятностный смысл относительно posterior, и его корректность зависит в том числе от выбранного prior и модели данных.</p>
    ${cite('bayes', 'Яндекс Учебник — байесовский подход к оцениванию')}
  `, 'Регуляризация и практика');

  add('linear-bias-variance', 'Разложение ошибки прогноза', 'Из чего состоит ошибка прогноза: bias² + variance + noise', `
    <p>Это, пожалуй, самая известная формула ML после y=kx+b. Её любят рисовать на собеседованиях в виде мишени с дырочками. Давайте не рисовать, а докажем.</p>
    <p>Зафиксируем новый x. Пусть f(x)=E[Y|x], σ²(x)=Var(Y|x), обучающая выборка D независима от нового ответа, а все нужные вторые моменты конечны. Обозначим m=E_D[f̂_D(x)] — средний прогноз по всем возможным обучающим выборкам.</p>
    ${proof('Раскрываем квадрат и проверяем смешанные члены', [
      ['f̂_D(x)−Y = (f̂_D(x)−m)+(m−f(x))−ε', 'Три слагаемых: разброс обученной модели, систематический промах и шум нового ответа.'],
      ['E_D[f̂_D−m]=0, &nbsp; E[ε|x]=0', 'Средние двух случайных слагаемых равны нулю.'],
      ['E[(f̂_D−m)ε|x]=0', 'Новый шум независим от обучения и в среднем равен нулю. Остальные смешанные члены обнуляются так же.'],
      ['E<sub>D,Y|x</sub>[(f̂_D(x)−Y)²]=(m−f(x))²+Var_D(f̂_D(x))+σ²(x)', 'Остаются ровно три квадратичных вклада. Никаких «примерно».']
    ])}
    <p>Это точное равенство при указанных условиях. Слагаемое <b>noise</b> нельзя уменьшить настройкой весов при том же наборе информации. Можно только поменять саму постановку: собрать дополнительные полезные признаки или измерять точнее. Регуляризация играет на первых двух слагаемых, а шум из мира она не удаляет. (А жаль.)</p>
  `, 'Регуляризация и практика');

  add('linear-feature-map', 'Нелинейность и новые признаки', 'Когда прямой мало: новые признаки', `
    <p>Помните параболу Y=U², которую прямая в упор не видела из-за нулевой ковариации? Лечится это одной строчкой: добавим признак φ(U)=(U,U²). Теперь модель b+w₁U+w₂U² содержит правильную функцию. Матрица X поменялась, но все доказательства МНК остались в силе: параметры по-прежнему входят линейно.</p>
    <p>Только не увлекайтесь. Полиномы высокой степени часто дают почти зависимые столбцы и легко переобучаются. Степень, преобразования и λ выбирают на validation. Категориальные признаки кодируют индикаторами, и тут ловушка: полный one-hot для одной категории вместе со свободным членом даёт точную линейную зависимость столбцов (сумма индикаторов равна столбцу единиц). Поэтому одну базовую категорию обычно выкидывают.</p>
    <p>И главное: низкий train-MSE ещё не означает адекватную модель. При добавлении признаков train-SSE у МНК может только уменьшиться: старое решение никуда не делось, достаточно поставить новым весам ноль. Это алгебра, а не доказательство того, что модель стала лучше обобщать.</p>
  `, 'Регуляризация и практика');

  add('linear-loss-catalog', 'Другие loss и метрики', 'MSE, MAE и квантили: разные loss — разные вопросы', `
    <p>Мы доказали, что квадрат ведёт к условному среднему. А если взять модуль? Тогда ответом будет <b>МЕДИАНА</b>. Для абсолютной ошибки при E[|Y||x]&lt;∞ и непрерывной условной функции распределения F_x производная E[|Y−c||x] по c равна 2F_x(c)−1, и ноль получается ровно на медиане. При атомах вместо производной берут субградиент, и медиана может быть не единственной.</p>
    ${proof('От модуля к условной медиане', [
      ['∂|y−c|/∂c = 1 при y&lt;c; −1 при y&gt;c', 'Разбираем две линейные ветки модуля. Точка y=c при непрерывном распределении имеет нулевую вероятность.'],
      ['∂E[|Y−c||x]/∂c = P(Y&lt;c|x)−P(Y&gt;c|x)', 'Разностные отношения модуля по абсолютной величине не больше единицы, поэтому теорема о мажорируемой сходимости разрешает занести предел под ожидание.'],
      ['P(Y&lt;c|x)−P(Y&gt;c|x)=F_x(c)−(1−F_x(c))=2F_x(c)−1', 'Производная равна нулю при F_x(c)=1/2 — это и есть медиана. Выпуклость абсолютной ошибки гарантирует глобальный минимум.']
    ])}
    ${eq('ρ_q(e)=e(q−𝟙[e&lt;0]), &nbsp; e=y−ŷ, &nbsp; q∈(0,1)<br>∂E[ρ_q(Y−c)|x]/∂c = F_x(c)−q', 'Квантильный (pinball) loss. При непрерывности оптимум — условная q-квантиль. Знак остатка важен: если взять ŷ−y, формулу придётся переписать.')}
    <p>Откуда F_x(c)−q? У квантильной ошибки производная по c равна 1−q при y&lt;c и −q при y&gt;c. Ожидание даёт (1−q)F_x(c)−q(1−F_x(c))=F_x(c)−q. Производная ограничена, так что перенос предела под ожидание снова законен. При атомах условие оптимума записывается как F_x(c−)≤q≤F_x(c).</p>
    <p>Ещё немного зоопарка. RMSE=√MSE возвращает ошибку в единицы ответа и без штрафа имеет тот же минимум. Но со штрафом √MSE+λ‖w‖² и MSE+λ‖w‖² — уже разные задачи. MAE меньше реагирует на выбросы в ответах, но от экстремальных признаков сама по себе не спасает.</p>
    <p>Huber loss равна e²/2 при |e|≤δ и δ(|e|−δ/2) иначе: возле нуля ведёт себя как квадрат, в хвостах — как модуль. Лучшее из двух миров. MAPE нестабильна около нулевого таргета (делить на ноль всё ещё нельзя). Итог: метрику выбирают по цене ошибки в реальной задаче, а не по тому, у кого производная красивее.</p>
  `, 'Регуляризация и практика');

  add('linear-validation', 'Проверка на новых данных', 'Минимум на train — ещё не победа', `
    <p>Мы потратили кучу сил, чтобы доказать, что МНК находит минимум ошибки на train. Плохая новость: это ничего не говорит о качестве на будущих данных. Помните «очень дорогую зубрёжку» из самого первого урока? Вот она.</p>
    <p>Поэтому данные делят на три части: <b>train</b> — чтобы подобрать веса, <b>validation</b> — чтобы выбрать признаки, λ и момент остановки, <b>test</b> — для финальной проверки. Если многократно выбирать модель по test, он перестаёт быть независимой оценкой и превращается во второй validation.</p>
    <p>Для временных данных разбиение должно уважать время: предсказывать прошлое по будущему — читерство, которое в продакшене не повторится. Если несколько строк относятся к одному человеку или устройству, делить часто нужно группами. А нормализацию, заполнение пропусков и отбор признаков обучаем только на train, в том числе внутри каждого фолда кросс-валидации.</p>
  `, 'Регуляризация и практика');

  add('linear-risk', 'Что оценивает validation', 'Что на самом деле оценивает validation', `
    <p>Чтобы не говорить о «качестве на будущих данных» на пальцах, введём <b>РИСК</b> — ожидаемую ошибку на новых объектах из того же распределения P, и его оценку по validation:</p>
    ${eq('R(f)=E<sub>(U,Y)∼P</sub>[(Y−f(U))²]<br>R̂<sub>val</sub>(f)=(1/m)Σ<sub>i=1</sub><sup>m</sup>(yᵢ−f(uᵢ))²')}
    <p>Если модель фиксирована и не видела validation, а validation — i.i.d. выборка из P с конечным риском, то E[R̂_val|f]=R(f). Вот почему validation вообще работает. Но если по той же выборке выбирать победителя среди многих моделей, его оценка становится оптимистичной: он победил в том числе за счёт удачного шума.</p>
    <p>А если будущее распределение меняется (цены на квартиры в 2016 и 2026 годах — немножко разные), прежний риск относится уже к другому P. От такого сдвига не защищает ни теорема Гаусса–Маркова, ни сколь угодно маленький градиент.</p>
  `, 'Регуляризация и практика');

  add('linear-diagnostics', 'Остатки и ограничения', 'Модель обучилась. Что дальше?', `
    <p>Обучили модель, получили веса. Расслабляться рано: теперь нужно посмотреть на остатки. Они часто подсказывают, какие из наших предположений о мире не выполняются. Вот небольшой справочник:</p>
    ${table(['Наблюдение','Что проверить'],[
      ['Изгиб на графике e против ŷ','Возможно, условное среднее нелинейно; попробовать преобразования признаков.'],
      ['Разброс остатков растёт','Возможна гетероскедастичность; классические SE могут врать.'],
      ['Ошибки идут сериями во времени','Возможна зависимость наблюдений; проверить временной split и ковариацию.'],
      ['Одна точка сильно меняет веса','Проверить выброс ответа и leverage — необычный вектор признаков.'],
      ['Веса скачут, прогноз почти тот же','Проверить ранг и маленькие сингулярные значения.']
    ],'Диагностика гипотез, а не автоматические диагнозы')}
    <p>И пара формул, чтобы не делать поспешных выводов:</p>
    ${eq('e=(I−P)ε ⇒ Cov(e|X)=σ²(I−P)<br>Var(eᵢ|X)=σ²(1−Pᵢᵢ)', 'Даже при независимом одинаково распределённом шуме обученные остатки обычно зависимы и имеют разные дисперсии. Сюрприз!')}
    <p>Диагональ Pᵢᵢ называется <b>LEVERAGE</b> («рычаг») и зависит только от геометрии признаков. Точка с большим leverage может притянуть прогноз к себе и получить маленький остаток. Поэтому маленький остаток ещё не доказывает, что точка ни на что не влияет: возможно, она как раз перетянула одеяло на себя. И помните: в МНК со смещением средний остаток всегда равен нулю по построению. Использовать это как подтверждение E[ε|X]=0 нельзя.</p>
  `, 'Регуляризация и практика');

  add('linear-causality', 'Пределы интерпретации', 'Коэффициент — ещё не причина', `
    <p>Финальное предостережение, и, пожалуй, самое важное. E[Y|U=x] описывает <em>наблюдаемую</em> связь: какой ответ мы в среднем видим у объектов с таким признаком. А E[Y|do(X=x)] — средний ответ, если мы <em>вмешаемся</em> и принудительно установим значение признака. Это разные вещи, и чтобы они совпали, нужны дополнительные условия и правильный дизайн исследования.</p>
    <p>Вспомните формулу пропущенного фактора: коэффициент может быть ненулевым даже при a₀=0, если γCov(U,Z)≠0. Например, подготовленность до курса влияет и на время, потраченное на задания, и на итоговый результат. Регрессия по времени смешает эти связи. Если заставить ученика сидеть над заданиями вдвое дольше, балл не обязан вырасти так, как обещает коэффициент. Значимый коэффициент и высокий R² сами по себе причинный эффект не выделяют.</p>
    <p>(Продажи мороженого отлично предсказывают число утоплений: обоих больше летом. Запрещать мороженое — плохая идея.)</p>
  `, 'Регуляризация и практика');

  add('linear-practice', 'Проверить понимание', 'О боже, домашка, неееет :(', `
    <p>Не переживайте, она короткая. Попробуйте ответить сами и только потом раскрывайте решение. Упражнения не влияют на прогресс и доступны в любой момент.</p>
    <details class="math-exercise"><summary>В выборке все x одинаковы. Почему нельзя назвать единственный наклон?</summary><p>Потому что Sₓₓ=0 и столбец x кратен столбцу единиц. При x=c любые a,b с ac+b=ȳ дают один и тот же оптимальный прогноз. Определён прогноз на train, но не наклон.</p></details>
    <details class="math-exercise"><summary>Шум Лапласа имеет среднее 0 и одинаковую дисперсию. МНК стал смещённым?</summary><p>Нет, если E[ε|X]=0 и X полного столбцового ранга. При независимых ошибках МНК остаётся BLUE. Изменилось другое: MLE теперь соответствует MAE, а не MSE, и точные нормальные t-интервалы без дополнительных аргументов применять нельзя.</p></details>
    <details class="math-exercise"><summary>Сделали два экземпляра каждой строки. Нужно ли вдвое усилить λ в MSE + λ‖w‖²?</summary><p>Нет. MSE и штраф остаются теми же, значит, оптимум не меняется: в формулах одновременно удваиваются XᵀX, Xᵀy и nλ. Но копирование не создаёт независимых данных, поэтому считать, что неопределённость весов уменьшилась как от новых наблюдений, нельзя.</p></details>
  `, 'Регуляризация и практика');

  add('linear-sources', 'Источники и маршрут чтения', 'Что почитать дальше', `
    <p>Эта глава — самостоятельный пересказ: доказательства собраны в одной системе обозначений, с собственным числовым примером и явными условиями применимости. Если пойдёте читать источники, будьте готовы: там может отличаться знак остатка, буквы a и b могут поменяться местами, а множители 1/n и 1/2 то появляются, то исчезают. Сравнивайте функцию потерь целиком, а не отдельные формулы.</p>
    <div class="theory-sources"><span>Русскоязычные материалы</span>
    ${Object.entries({habr:'Андрей Хлевнюк — «Основы линейной регрессии»: ковариация и геометрия',linear:'Яндекс Учебник — линейные модели: МНК и регуляризация',probability:'Яндекс Учебник — вероятностный подход: шум и loss',bayes:'Яндекс Учебник — байесовский подход: prior и posterior',statistics:'О. А. Демидова, НИУ ВШЭ — Гаусс–Марков, оценки дисперсии и интервалы (PDF)'}).map(([key,label])=>`<a class="theory-reference" href="${reading[key]}" target="_blank" rel="noreferrer">${label} <span>↗</span></a>`).join('')}
    </div>
    <p>Если заметили неточность или ошибку — пишите, исправим. Спасибо за внимание!</p>
  `, 'Регуляризация и практика');

  return {
    route: 'linear', title: 'Линейная<br><span>регрессия.</span>', label: 'алгоритм / математический разбор',
    lead: 'Первая настоящая модель ML — и сразу полный набор математики: от производных a и b до матричной проекции, случайного шума и доверительных интервалов. Доказываем формулы, считаем руками и выясняем, где они перестают работать.',
    outline: blocks.map(({id,label,group}) => [id,label,group]),
    content: blocks.map(({id,label,title,body},i) => section(id, `${String(i+1).padStart(2,'0')} / ${label}`, title, body)).join('')
  };
}
